  ('SUETER', 'ELEMENTAL - Sambil', 'S', 'NEGRO', 1),
  ('SUETER', 'ELEMENTAL - Sambil', 'S', 'VINOTINTO', 9),
  ('SUETER', 'ELEMENTAL - Sambil', 'XL', 'AMARILLO', 6),
  ('SUETER', 'ELEMENTAL - Sambil', 'XL', 'BEIGE', 1),
  ('SUETER', 'ELEMENTAL - Sambil', 'XL', 'BLANCO', 4),
